// Pseudo batch ICA flow for 4-sensor data
function batchICA(X, nComponents){
  // X: [4 x N]
  // 1) center
  const Xc = center(X);
  // 2) whiten
  const Xw = whiten(Xc);
  // 3) ICA step (gradient or fixed-point)
  const W = icaGradientStep(Xw, nComponents);
  return W;
}
```

